var pgnList = append(append([]PgnInfo{}, typedPgnList...), catalogOnlyList...)

// init builds the PgnInfoLookup and UnseenLookup maps from the generated pgnList.
// It also sets the Self pointer on each PgnInfo so generated code can reference its
// own descriptor.
func init() {
	PgnInfoLookup = make(map[uint32][]*PgnInfo)
	UnseenLookup = make(map[uint32][]*PgnInfo)
	EncoderLookup = make(map[uint32]func(Message) ([]byte, error))

	// Index every known PGN in the generated pgnList.
	for i, pi := range pgnList {
		// Set Self to point back to this entry's address in the slice.
		pgnList[i].Self = &pgnList[i]
		if PgnInfoLookup[pi.PGN] == nil {
			PgnInfoLookup[pi.PGN] = make([]*PgnInfo, 0)
		}
		PgnInfoLookup[pi.PGN] = append(PgnInfoLookup[pi.PGN], &pgnList[i])
		if pgnList[i].Encoder != nil {
			EncoderLookup[pi.PGN] = pgnList[i].Encoder
		}
		if pgnList[i].Decoder == nil {
			if UnseenLookup[pi.PGN] == nil {
				UnseenLookup[pi.PGN] = make([]*PgnInfo, 0)
			}
			UnseenLookup[pi.PGN] = append(UnseenLookup[pi.PGN], &pgnList[i])
		}
	}
}
